static void Stack_Init(void)
{
	NvM_Init();
	MEM1_Init();
	MEM2_Init();
	MEM_Init(NULL);
}

static void NvmW_Write(uint32 BlockId)
{
	//printf("ohh\n");
	// BlockId = ;
	for(int i=2; i<BlockId; i++)	{
	// printf("hello  %d\n ",i);

			uint8 result=0u;
			NvM_WriteBlock(i, NULL);
			do
		{
				NvM_MainFunction();
				MEM1_MainFunction();
				MEM2_MainFunction();
				MEM_MainFunction();
				NvM_GetErrorStatus(i,&result);
		}while(result==2);
	}
}

static void Gen_MemCpy(uint8* dest, uint8* src, uint32 len)
{
	uint32 i;
	for(i=0; i<len;i++)
	{
		dest[i]=src[i];
	}
}

